/* Small choice callbacks keep the eight-episode routes continuous. */
(()=>{
const cast=Object.fromEntries(CAST.map(c=>[c.id,c]));
const event=(id,n)=>cast[id].events[n-1];
const line=(id,n,i,text)=>{const e=event(id,n);e[6][i]=text;if(i<3)e[i+1]=text;};
const choice=(id,n,index,text,reply)=>{const a=event(id,n)[4+index];a[0]=text;a[2]=reply;};
const echo=(id,n,at,yes,no)=>{const e=event(id,n);e[7]=[...(Array.isArray(e[7])?e[7]:e[7]?[e[7]]:[]),{at:at-1,yes,no}];};
window.STORY_VARIANTS={};
const variant=(id,n,at,yes,no)=>{(window.STORY_VARIANTS[id]??={})[n-1]={at:at-1,yes,no};};
// A completed call cannot be answered again.
choice('honey',5,1,'다음 연락이 오면 제가 옆에서 거절하는 걸 도와드릴까요?','마음은 고마워요. 그래도 먼저 내가 답해볼게요. 어려우면 그때 도와줘요.');
// Avoid assuming the player praised the song earlier.
line('ohwayo',5,1,'아, 미안해. 어젯밤엔 혼자 연습하다가 그렇게 늦어진 줄 몰랐네.');
const oh8=[...event('ohwayo',8)[6]];
const oh8away=[...oh8];
oh8away[0]='공연이 끝났다는 오화요의 문자를 받고 공연장으로 돌아왔다. 관객들이 떠난 객석 앞에서 그녀가 접힌 악보를 들고 기다리고 있었다.';
oh8away[1]='문자 보고 와줬네. 지난 리허설 때 네가 앉아 있던 자리를 보니까 조금 덜 떨리더라.';
variant('ohwayo',8,7,oh8,oh8away);
// Repair a disagreement explicitly before returning to the shared story.
const y7=[...event('yui',7)[6]];
const y7no=[...y7];
y7no[0]='따로 밥을 먹자던 말이 마음에 남아 담유이에게 먼저 연락했다. 서운했던 건 기다림이었다고 설명하고, 다시 식사에 초대했다. 문에는 장난스럽게 주방 출입 금지라고 써 붙였다.';
y7no[1]='다시 말해줘서 고마워. 늦을 땐 꼭 연락할게. 오늘은 주방장님 말씀대로 얌전히 앉아 있을까?';
variant('yui',7,6,y7,y7no);
const m7=[...event('mone',7)[6]];
const m7no=[...m7];
m7no[0]='모네에게 먼저 연락해, 멀어질까 겁이 나서 가까워질 이유가 없다는 말을 했다고 털어놓았다. 선배는 내 이야기를 듣고 나서 빈 종이 한 장을 펼쳤다.';
m7no[1]='말해줘서 고마워. 아직 결과도 모르는데 우리 사이부터 끝난 것처럼 생각하지는 말자. 가능한 약속부터 적어볼까?';
variant('mone',7,6,m7,m7no);
ROMANCE_ENDINGS.rose[0][2]=ROMANCE_ENDINGS.rose[0][2].replace('말을 고르듯 천천히 내렸다.','말을 고르듯 천천히 손을 내렸다.');
choice('popo',4,1,'많이 놀랐겠다. 잠깐 쉬고 다시 확인할까?','응. 물 한 잔 마시고 올게. 사과는 했으니까, 이제 같은 실수 안 나게 동료랑 맞춰봐야지.');
event('popo',4)[5][1]=1;
cast.ori.outings[0][1]='흰 셔츠에 검정 베스트와 바지를 입은 오리고기가 공원 벤치에서 이어폰을 꺼냈다. 산책하다 말고 아까 이야기한 재즈 한 곡이 떠올랐다고 했다.';
cast.ori.outingMoods=[3,4];cast.ori.outingMinProgress=[2,6];
// Two remembered decisions per member, with short branches that rejoin.
echo('ohwayo',8,4,'연습실에서 틀려도 듣겠다고 했던 말을 그녀가 기억하고 있었다. 완벽하지 않았던 소절도 오늘은 끝까지 이어졌다.','곡을 바꾸자는 내 의견과 달리 그녀는 처음 고른 곡을 끝까지 불렀다. 나는 무대를 마친 그녀에게 그 선택이 잘 어울렸다고 말했다.');
echo('dragon',7,5,'근무표 말고 시간을 맞추자던 약속대로, 이번에는 둘 다 쉬는 날을 골랐다.','편의점에 오는 재미가 없겠다는 말은 서운했을 거라고 먼저 사과했다. 그녀는 새 지원서 이야기도 들어달라며 가방을 열었다.');
echo('yui',8,5,'행사 메뉴를 함께 줄여본 뒤로, 달력에도 쉬는 날을 먼저 남기는 습관이 생겼다.','내가 일을 다 맡겠다고 했던 날을 떠올렸다. 이번 달력에는 어느 한쪽만 애쓰지 않도록 각자 쉬는 시간도 적었다.');
echo('aya',7,4,'전화할 내용을 함께 적던 날처럼, 이번에도 아야가 부탁한 만큼만 곁에서 도왔다.','대신 전화하겠다고 나섰던 날과 달리, 오늘은 아야에게 어떤 도움이 필요한지 먼저 물었다.');
echo('siyo',7,4,'그날 마지막 진입을 기억한다고 말해준 뒤부터, 그녀는 내 앞에서 실수한 장면도 숨기지 않았다.','이겼으니 신경 쓰지 말라던 말이 떠올랐다. 오늘은 결과부터 꺼내지 않고, 헤드셋을 벗은 그녀가 말을 시작할 때까지 기다렸다.');
echo('mone',8,4,'다음 장을 함께 읽고 싶다던 말을 선배가 책갈피 여백에 작게 적어두었다.','결말을 빨리 알면 편하다고 했던 나도, 이제는 선배가 말을 고르는 시간을 서두르고 싶지 않았다.');
echo('rose',7,5,'점심에 추천을 보내기로 정한 뒤, 그녀는 답을 재촉하지 않고 내가 읽은 장면을 물었다.','알아서 적당히 보내라던 말이 너무 막연했다며, 나는 점심에는 편하게 보내줘도 된다고 덧붙였다. 그녀가 그제야 고개를 끄덕였다.');
echo('siho',7,6,'게임에서 실수한 날에도 함께하자고 했던 뒤로, 그녀는 잘 모르는 그림 앞에서도 편하게 질문했다.','지난번에는 준비하라는 조언부터 했다고 사과했다. 잘하지 않아도 함께 있고 싶다는 말을 듣자 그녀가 전시 지도를 조금 편하게 폈다.');
echo('popo',6,4,'실수를 고치고 사과한 일을 알아줘서 고마웠다고 그녀가 말했다. 오늘은 주문표를 떠올리는 대신 발걸음을 늦췄다.','잠깐 쉬자던 내 말을 기억했다며 그녀가 벤치를 가리켰다. 이제는 지치기 전에 쉬어도 된다고 덧붙였다.');
echo('popo',7,5,'이번에는 출발 전에 둘이 날씨를 확인하고 실내로 약속을 바꿨다. 먼저 상의하겠다는 약속이 지켜졌다.','취소된 휴무에 서운했던 마음을 다시 이야기했다. 그녀도 약속을 바꾸기 전에 먼저 묻겠다고 답했고, 둘이 오늘 갈 곳을 골랐다.');
echo('ori',6,3,'스스로 고른 옷이면 충분하다던 말을 기억했는지, 그녀는 오늘 입고 나온 옷을 내게 먼저 보여줬다.','옷을 정해주겠다고 했던 말을 고쳐, 이번에는 어떤 점이 마음에 들어 골랐는지 물었다. 그녀가 소매를 펴 보이며 설명했다.');
echo('ori',7,5,'원하지 않는 장면은 남기지 않기로 했던 날처럼, 오늘도 우리는 카메라보다 서로의 마음을 먼저 확인했다.','얼굴을 가리면 되지 않겠느냐던 말을 떠올렸다. 이번에는 기록으로 남길지부터 그녀에게 물었고, 그녀는 오늘은 그냥 이야기하고 싶다고 했다.');
// Episode eight opens the question; the optional romance ending makes the commitment.
const finalChoices={
honey:[['업무 없는 날에도 누나를 더 알아가고 싶어요.','좋아요. 다음에는 네가 좋아하는 곳에서 만나봐요.'],['좋은 시간이었어요. 마음은 조금 더 알아보고 싶어요.','괜찮아요. 대답부터 정해놓고 만날 필요는 없죠.']],
ohwayo:[['서툴러도 다시 해보는 모습이 좋아요. 노래가 끝나도 누나랑 있고 싶고요.','그런 데까지 보고 있었구나. 다음에는 노래 없이도 우리 얘기를 해보자.'],['좋은 점이 많아요. 제 마음은 조금 더 천천히 말하고 싶어요.','응. 오늘 바로 답을 내달라는 건 아니야. 여기 와준 것부터 고마워.']],
dragon:[['소꿉친구라는 말 말고도, 요즘 네가 자꾸 생각나.','나만 그런 건 아니었네. 내일은 지금의 우리 얘기를 좀 더 해보자.'],['오래 알던 너라서 내 마음도 천천히 확인하고 싶어.','알겠어. 아는 사이니까 다 안다고 넘기지만 말자. 내일 만나서 얘기해.']],
yui:[['둘이 더 알아가는 약속이라고 적고 싶어요.','좋다. 그날은 요리도 쉬고, 우리 얘기를 더 하자.'],['아직 이름은 정하지 말고, 같이 저녁부터 먹어요.','그래. 식탁 앞에서 천천히 얘기하면 되지.']],
aya:[['저도 아야를 만나고 싶어서 와요. 다음에도 초대해줘요.','네. 잘한 일이 없는 날에도 그냥 보고 싶다고 말해볼게요.'],['고마워요. 제 마음도 서두르지 않고 알아보고 싶어요.','네. 초대에 정답을 붙이지는 않을게요. 오늘은 편하게 쉬어요.']],
siyo:[['응. 나도 너 보고 싶어서 내려가는 거야.','그 말 들으니까 더 떨리네. 그래도 와. 같이 걷자.'],['내려갈게. 마음 얘기는 조금 천천히 해도 될까?','응. 오늘 답부터 정하라는 건 아니야. 얼굴 보고 얘기하자.']],
mone:[['다음 장도 선배랑 읽고 싶어요. 제 마음도 더 알고 싶고요.','나도 그래. 제목은 천천히 정해도 괜찮아.'],['아직 이름은 잘 모르겠어요. 조금 더 이야기해도 될까요?','물론이지. 모르는 마음을 정답처럼 말할 필요는 없어.']],
rose:[['나도 농담 뒤에 숨지 않고, 너를 더 알아가고 싶어.','그럼 오늘은 추천 말고 우리 얘기부터 해볼까요.'],['바로 대답하기보다는 내 마음을 조금 더 생각하고 싶어.','좋아요. 급하게 대사 맞출 필요는 없죠. 같이 걷는 건 괜찮고요?']],
popo:[['나도 너 만나는 날이 기다려져. 더 자주 보고 싶어.','그 말 들으니까 오늘 옷 고르길 잘했다 싶네. 좀 더 걷자.'],['고마워. 내 마음도 천천히 알아봐도 될까?','응. 오늘 답부터 정하라고 꾸민 건 아니다. 같이 있는 거부터 좋다.']],
siho:[['저도 만날 때마다 시호가 더 궁금해져요.','그럼 다음에도 먼저 연락해볼게요. 우리 얘기를 조금씩 더 해요.'],['말해줘서 고마워요. 제 마음은 조금 더 생각해도 될까요?','네. 기다리는 동안 눈치만 보지는 않을게요. 편하게 이야기해줘요.']],
ori:[['저도 일 얘기 없이 누나를 더 만나고 싶어요.','좋아요. 오늘은 다음 약속도 같이 골라봐요.'],['고마워요. 제 마음도 천천히 알아보고 싶어요.','알겠어요. 오늘 다 정하지 않아도 괜찮아요. 조금 더 걸을까요?']]
};
for(const [id,options] of Object.entries(finalChoices)){
  options.forEach((a,i)=>choice(id,8,i,...a));
  event(id,8)[5][1]=1; // Taking time is a valid, considerate response.
}
line('siho',8,5,'당신이 자꾸 생각나요. 온라인이 아닐 때도요. 오늘은 그 말을 먼저 해보고 싶었어요.');
line('popo',8,5,'니 만나는 날이 기다려진다. 일하는 나도 쉬는 나도, 니한테는 더 보여주고 싶다.');
line('ori',8,5,'일이 없어도 너를 만나고 싶어요. 오늘은 그런 마음이 있다는 걸 먼저 말해보고 싶었어요.');
// Research remains undecided, but the characters explicitly agree how to handle it.
ROMANCE_ENDINGS.mone[2][2]=ROMANCE_ENDINGS.mone[2][2].replace('우리는 미래의 답을 전부 알지 못했다.', '연구실 지원 결과는 아직 기다리는 중이었다. 선배는 소식이 오면 바로 알려주겠다고 했고, 우리는 다른 도시에 가더라도 먼저 가능한 날짜를 맞춰보기로 했다.\n우리는 미래의 답을 전부 알지 못했다.');
// Optional outings must not reveal events before their main-story introduction.
cast.ohwayo.outingMinProgress=[1,8];
cast.ohwayo.outings[1][0]='공연 뒤의 휴식';
cast.ohwayo.outings[1][1]='공연을 마친 뒤 처음 함께 쉬는 날이었다. 오화요는 노래 대신 내 이야기를 듣고 싶다며 찻잔을 감싸 쥐었다.';
line('ohwayo',7,0,'공연을 앞둔 리허설 날, 음향에 문제가 생겼다. 오화요는 마이크를 내리고 텅 빈 객석을 바라봤다.');
line('ohwayo',7,3,'공연 날 마지막 말은 노래 끝나고 해도 될까? 미리 하면 노래를 못 할 것 같아.');
line('ohwayo',7,5,'공연 날에도 끝날 때까지 기다려줄 거지?');
choice('ohwayo',7,1,'공연 끝나면 문자 주세요.','응. 그날 끝나면 바로 보낼게. 그때 잠깐 만나자.');
cast.dragon.outings[0][3][1]='다음 근무 얘기 꺼내기';
const moneSecond=event('mone',2);
moneSecond[3]='선배는 책을 넣으며 내 눈치를 살폈다. 퍼즐이 적힌 원래 책갈피는 다음에 이어서 풀자며 내게 맡겼다.';
if(moneSecond[6])moneSecond[6][2]=moneSecond[3];
cast.mone.outings[0][5]='그렇게 읽을 수도 있겠네. 그 이유도 재미있다. 한 번 더 읽어봐야겠어.';
// These cardigans also appear before the ending, on existing visits.
line('yui',6,0,'약속한 식사 시간이 지났는데 연락이 없었다. 나는 음식이 식어가는 식탁 앞에서 기다렸다. 잠시 뒤 초인종이 울리고, 하늘색 카디건을 걸친 담유이가 문 앞에 나타났다.');
line('siyo',8,4,'창밖에서 같은 골목의 차 소리가 들렸다. 집 앞이라는 말에 창가로 다가가니, 크림색 카디건을 걸친 하시요가 올려다보고 있었다.');
line('siho',5,0,'카페에서 류시호에게 게임 친구들의 모임 이야기를 꺼냈다. 흰 카디건에 꽃 장식을 단 그녀는 초대 메시지를 읽다가 조심스럽게 나를 봤다.');
})();
